int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & (1 << CAPABILITY_STATUS))) {
        return -EINVAL;
    }

    if (arg >= MAX_DRIVE_STATES) {
        return -EINVAL;
    }

    return cdi->ops->get_status(cdi, arg);
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & CDC_STATUS)) {
        return -EINVAL;
    }

    if (arg > CDROM_MAX_SLOT) {
        return -EINVAL;
    }

    if (arg == CDROM_CURRENT) {
        return cdi->current_status;
    } else {
        return cdi->slot_status[arg];
    }
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->mask & CDC_GET_STATUS)) {
        return -EINVAL;
    }

    if (arg > CDROM_MAX_DRIVE_SLOT) {
        return -EINVAL;
    }

    if (arg == 0) {
        return cdi->current_slot;
    } else {
        return cdi->slot_status[arg];
    }
}

int get_cdrom_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->capabilities & CDC_GET_STATUS)) {
        return -EINVAL;
    }

    if (!is_valid_operation(arg)) {
        return -EINVAL;
    }

    return cdi->ops->get_status(cdi, arg);
}

int get_drive_status(struct cdrom_device_info *cdi, unsigned long arg) {
    if (!(cdi->mask & (1 << CDROM_DRIVE_STATUS))) {
        return -EINVAL;
    }

    if ((arg != CDSL_CURRENT) && (arg != CDSL_REQ_SLOTS) && (arg != CDSL_CURRENT_SLOT)) {
        return -EINVAL;
    }

    if (arg == CDSL_CURRENT) {
        return cdi->current_drive_state;
    } else if (arg == CDSL_REQ_SLOTS) {
        return cdi->num_slots;
    } else {
        return cdi->current_slot;
    }
}
